 	const lowerQuery = query.toLowerCase();
 	const results: SearchResult[] = [];

 	// Search tasks
 	for (const task of snapshot.tasks) {
 		if (
 			task.title.toLowerCase().includes(lowerQuery) ||
 			task.slugs.some((s) => s.includes(lowerQuery))
 		) {
 			results.push({
