 				ulid: item._ulid,
 				title: item.title,
 				matchedFields: ['title']
 			});
 		}
 	}

 	// Search inbox
 	for (const inbox of snapshot.inbox) {
 		if (inbox.text.toLowerCase().includes(lowerQuery)) {
